var _ = Describe("Events", func() {
	Describe("SSE delivery", func() {
		It("delivers request events only to other sessions of the sender", func() {
			ctx := request.WithClientUniqueId(context.Background(), "origin")
			ctx = request.WithUser(ctx, model.User{UserName: "alice"})
			msg := (&broker{}).prepareMessage(ctx, &RefreshResource{})
			Expect(msg.shouldDeliver(client{username: "alice", clientUniqueId: "origin"})).To(BeFalse())
			Expect(msg.shouldDeliver(client{username: "alice", clientUniqueId: "other"})).To(BeTrue())
			Expect(msg.shouldDeliver(client{username: "bob", clientUniqueId: "other"})).To(BeFalse())
		})

		It("uses the Subsonic username when there is no native user", func() {
			ctx := request.WithClientUniqueId(context.Background(), "origin")
			ctx = request.WithUsername(ctx, "alice")
			msg := (&broker{}).prepareMessage(ctx, &RefreshResource{})
			Expect(msg.shouldDeliver(client{username: "alice", clientUniqueId: "other"})).To(BeTrue())
			Expect(msg.shouldDeliver(client{username: "bob", clientUniqueId: "other"})).To(BeFalse())
		})

		It("broadcasts events without a sender client ID", func() {
			ctx := request.WithUsername(context.Background(), "alice")
			msg := (&broker{}).prepareMessage(ctx, &RefreshResource{})
			Expect(msg.shouldDeliver(client{username: "bob", clientUniqueId: "other"})).To(BeTrue())
		})
	})

	Describe("Event", func() {
		type TestEvent struct {
			baseEvent
			Test string
		}

		It("marshals Event to JSON", func() {
			testEvent := TestEvent{Test: "some data"}
			data := testEvent.Data(&testEvent)
			Expect(data).To(Equal(`{"Test":"some data"}`))
			name := testEvent.Name(&testEvent)
			Expect(name).To(Equal("testEvent"))
		})
	})

	Describe("RefreshResource", func() {
		var rr *RefreshResource
		BeforeEach(func() {
			rr = &RefreshResource{}
		})

		It("should render to full refresh if event is empty", func() {
			data := rr.Data(rr)
			Expect(data).To(Equal(`{"*":"*"}`))
		})
		It("should group resources based on name", func() {
			rr.With("album", "al-1").With("song", "sg-1").With("artist", "ar-1")
			rr.With("album", "al-2", "al-3").With("song", "sg-2").With("artist", "ar-2")
			data := rr.Data(rr)
			Expect(data).To(Equal(`{"album":["al-1","al-2","al-3"],"artist":["ar-1","ar-2"],"song":["sg-1","sg-2"]}`))
		})
		It("should send a * for when Any is used as id", func() {
			rr.With("album", Any)
			data := rr.Data(rr)
			Expect(data).To(Equal(`{"album":["*"]}`))
		})
	})
})
