func TestClientUniqueID(t *testing.T) {
	for _, tc := range []struct {
		name, header, cookie, want string
		setCookie                  bool
	}{
		{name: "header overrides cookie", header: "new", cookie: "old", want: "new", setCookie: true},
		{name: "cookie fallback", cookie: "old", want: "old"},
		{name: "missing ID"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := httptest.NewRequest(http.MethodGet, "/", nil)
			if tc.header != "" {
				r.Header.Set(consts.UIClientUniqueIDHeader, tc.header)
			}
			if tc.cookie != "" {
				r.AddCookie(&http.Cookie{Name: consts.UIClientUniqueIDHeader, Value: tc.cookie})
			}
			w := httptest.NewRecorder()
			clientUniqueID(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
				got, ok := request.ClientUniqueIdFrom(r.Context())
				if got != tc.want || ok != (tc.want != "") {
					t.Errorf("context ID = %q, %v; want %q", got, ok, tc.want)
				}
			})).ServeHTTP(w, r)
			cookies := w.Result().Cookies()
			if tc.setCookie {
				if len(cookies) != 1 || cookies[0].Value != tc.want || !cookies[0].HttpOnly || cookies[0].Path != "/" || cookies[0].MaxAge != consts.CookieExpiry {
					t.Errorf("response cookies = %+v", cookies)
				}
			} else if len(cookies) != 0 {
				t.Errorf("unexpected response cookies = %+v", cookies)
			}
		})
	}
}
import { fetchUtils } from 'react-admin'
import { baseUrl } from '../utils'
import config from '../config'
import jwtDecode from 'jwt-decode'
import { clientUniqueID, clientUniqueIDHeader } from '../clientUniqueID'

const customAuthorizationHeader = 'X-ND-Authorization'

const httpClient = (url, options = {}) => {
  url = baseUrl(url)
  if (!options.headers) {
    options.headers = new Headers({ Accept: 'application/json' })
  }
  options.headers.set(clientUniqueIDHeader, clientUniqueID)
  const token = localStorage.getItem('token')
  if (token) {
    options.headers.set(customAuthorizationHeader, `Bearer ${token}`)
  }
  return fetchUtils.fetchJson(url, options).then((response) => {
    const token = response.headers.get(customAuthorizationHeader)
    if (token) {
      const decoded = jwtDecode(token)
      localStorage.setItem('token', token)
      localStorage.setItem('userId', decoded.uid)
      // Avoid going to create admin dialog after logout/login without a refresh
      config.firstTime = false
    }
    return response
  })
}

